INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES
(97894,'ruRU','Дела в Аубердине','Проведайте Горбольда Сталерука в Аубердине на Темных берегах.','Рад знакомству! Меня зовут Боргус, из того самого семейства Сталеруков. На Сталерука всегда можно положиться, если нужна честная сделка!$B$BНесколько недель назад мой брат Горбольд пристроился к торговой лавке в Аубердине. Там можно неплохо заработать, снабжая корабли, уж поверь мне! Вот везунчик.$B$BС тех пор от него ни слуху ни духу. Не заглянешь к нему, если будешь в тех краях?$B$BВ гавани стоит новый корабль, он отвезет тебя прямо туда. Иди к самому южному причалу, не промахнешься!',0),
(95161,'ruRU','Помни, что я люблю тебя','Принесите запятнанное кровью письмо Аветте Хвористинке в Сумеречный лес.','Если вы ищете Джереми Пленное Сердце, лучше всего поговорите с его новой приемной матерью, Аветтой Хвористинкой, в Сумеречном лесу. Милая женщина. Наверняка ей пригодится лишняя пара рук, но это все же лучше, чем оставаться в приюте.$B$BЕсли увидите малыша Джереми, обязательно передайте ему, что мы все о нем думаем, хорошо?',0),
(97234,'ruRU','Место для чтения','Отнесите завернутую литературу в библиотеку Штормграда.','Вы пришли обсудить глубинный смысл наших знаменитых легенд? Нет?$B$BЧто ж, когда закончите осматриваться, не могли бы вы отнести это в библиотеку? Мы меняем часть не самых популярных сочинений на что-нибудь посовременнее. У меня есть список томов, которые библиотекарь, я уверен, сможет раздобыть для нас по нашему давнему уговору.$B$BЕсли поможете, угощение в клубе за наш счет.',0),
(95065,'ruRU','Время рыбачить','Принесите Гилберту Грею в гавань Штормграда 1 |4блесну:блесны:блесен; и 3 |4выползка:выползков:выползков;.','Какой вид... Лучшего старику и желать нельзя.$B$BРыба сейчас так и клюет, а у меня осталась последняя наживка. У тебя, случаем, не найдется лишних рыболовных припасов? Конечно нет, прости. Я так обрадовался, что снова закину удочку, что и не подумал: не каждый ведь носит снасти с собой, куда бы ни пошел.$B$BНе поможешь пополнить мои запасы? У Катрин Лиланд есть всякие рыболовные товары, ее лавка у каналов, к западу от Торгового квартала. Скажи ей, что тебя прислал старина Грей.',0),
(97220,'ruRU','Просьба Филмора','Отнесите декларируемый груз к входу в хранилище. Оно находится в магазине "Сыры Триаса" в Торговом квартале.','Всю неделю нам каждый день не хватает портовых грузчиков.$B$BНе поможете нам с графиком поставок?$B$BОтнесите эту посылку ко входу в хранилище. Он находится в магазине "Сыры Триаса", на втором этаже. Хозяйка, Илана, хорошо знает, как принимать такие поставки. Через это хранилище часто идут грузы, которые нужно доставить без лишнего шума: офицеры стражи любят устраивать торжественные сюрпризы.',0)
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES
(95161,'ruRU','Да? Что вам нужно?',0),
(97234,'ruRU','Пожалуйста, говорите потише.',0),
(95065,'ruRU','Рыболовные припасы при тебе?',0),
(97220,'ruRU','Хотите наполнить ящик нашими лучшими выдержанными сырами?',0)
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES
(97894,'ruRU','Тебя прислал старина Борги? Вечно он обо мне заботится.$B$BЛишняя пара рук нам здесь точно не помешает. После недавней трагедии торговля почти встала, и, думаю, ты можешь помочь все исправить.',0),
(95161,'ruRU','О нет...$B$BСпасибо, что принесли это, но, думаю, Джереми еще не готов это увидеть. Попечительница Найтингейл сказала, что мой малыш Джереми не произнес ни слова после нападения на Лордерон, и я не собираюсь его торопить. Если показать ему это сейчас, ему станет только больнее.$B$BНе смотрите на меня так. Я не стану скрывать от него его прошлое, но ему нужно время, чтобы залечить раны. Я отдам ему это, когда он подрастет. Спасибо, что зашли, но, думаю, вам пора.',0),
(97234,'ruRU','Посмотрим... Книжный клуб Роя, не так ли? Узнаю эту манеру упаковки.$B$BЧто ж, если он говорит, что людям интересно обсуждать именно это, я не против. Книги нам всегда возвращают в том же виде, в каком мы их одалживали, так что мы знаем: к ним относятся с уважением, какими бы дерзкими ни были слова на их страницах.',0),
(95065,'ruRU','Как раз вовремя! На последнюю наживку поймал здоровенную рыбину. Отличный сегодня денек. Клюет вовсю!$B$BЗнаешь что, раз уж ты так любезно $Gпомог:помогла; старику не остаться без дела, возьми-ка пару рыбок в дорогу.',0),
(97220,'ruRU','Ох, батюшки. Вы думаете, мы сами потащим это вверх по лестнице? За сохранность ценного груза отвечаете вы, пока не сдадите его.',0)
