-- Russian story, progress and reward text for 5 Forever quests that a Russian player reported (2026-11-07) as showing
-- English text on a Russian client: 97894 Business in Auberdine, 95161 Remember That I Love You, 97234 Reading Room,
-- 95065 Fishin' Time, 97220 Philmor's Favor.
-- Their Russian title and objective line came in with 2026_11_06_01 (Wowhead tooltips), but a tooltip has no story
-- text, so the quest window, the progress text and the reward text stayed English.
-- Text: our own translation of the English text, using the Russian names already in the database
-- (NPCs, places, quest titles). No official Russian text was available to us for these quests; replace it with the
-- official text if it turns up.
-- Only fills a missing or empty Russian field; an existing one is kept. Safe to run again.
SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE
  `QuestDescription`=IF(`QuestDescription` IS NULL OR `QuestDescription`='',VALUES(`QuestDescription`),`QuestDescription`);

ON DUPLICATE KEY UPDATE
  `CompletionText`=IF(`CompletionText` IS NULL OR `CompletionText`='',VALUES(`CompletionText`),`CompletionText`);

ON DUPLICATE KEY UPDATE
  `RewardText`=IF(`RewardText` IS NULL OR `RewardText`='',VALUES(`RewardText`),`RewardText`);
